"""R17: tema, selección de ideas y resumen con textos originales."""
import json
from pathlib import Path
U=[]
def unit(id,after,title,exp,hint,rows):
 activities=[]
 for i,(story,q,answer,quote,why,wrong1,wrong2) in enumerate(rows):
  assert quote in story,(id,quote)
  options=[answer,wrong1,wrong2];assert len(set(options))==3
  k=i%3;options=options[k:]+options[:k]
  activities.append(dict(id=id+'-v'+str(i+1),enunciado=q,respuesta_correcta=answer,opciones=options,paso_resuelto='El texto dice «'+quote+'». '+why,visual=dict(tipo='lectura',titulo='Texto para releer',texto=story)))
 first=rows[0]
 U.append(dict(id=id,tema='comprension_lectora_literal_inferida',despues_de=after,titulo=title,explicacion=exp,ejemplo=first[1]+' '+first[2]+'.',pasos=['Buscamos la pista: «'+first[3]+'».',first[4]],pista=hint,visual=activities[0]['visual'],actividades=activities))
unit('leng_res_tema','leng_prof_limites','Reconocer de qué trata todo el texto','El tema responde de qué trata el texto y puede nombrarse con pocas palabras. Buscamos lo que une sus frases. Un objeto que aparece una sola vez puede ser un detalle; un tema demasiado amplio puede dejar afuera lo especial de esta lectura.','Buscá qué asunto comparten las frases.',[
('En el club, los vecinos reciben libros usados. Revisan que estén completos y los ordenan por edades. Después los prestan a las familias. Una mesa azul sirve para anotar los préstamos.','¿Cuál es el tema del texto?','La biblioteca del club','los prestan a las familias','Recibir, ordenar y prestar libros son tareas de esa biblioteca. El color de la mesa es un detalle.','El color de una mesa','Todos los deportes del club'),
('En el patio escolar, la clase preparó canteros. Sembró lechuga y zanahoria. Cada semana se turna para regar y retirar las hierbas que crecen entre las plantas.','¿Qué tema une las acciones?','El cuidado de la huerta escolar','se turna para regar','Preparar, sembrar y cuidar forman parte del trabajo en la huerta.','La pintura del patio','Todas las comidas de la escuela'),
('Mara separa los papeles que ya no usa. Aprovecha el reverso para dibujar y guarda los recortes para hacer collages. Así necesita menos hojas nuevas.','¿De qué trata principalmente?','Reutilizar papel','necesita menos hojas nuevas','Las acciones muestran distintas maneras de volver a usar papel.','Comprar lápices','Todos los pasatiempos de Mara'),
('La radio escolar sale al aire los viernes. Un grupo prepara noticias, otro entrevista a los invitados y otro elige música. Todos revisan el programa antes de transmitirlo.','¿Qué tema reúne las frases?','La preparación de la radio escolar','Todos revisan el programa','Noticias, entrevistas y música son partes del mismo programa.','Los gustos de un invitado','Todas las actividades del viernes'),
('El museo prepara una muestra de juguetes antiguos. El equipo limpia las piezas, escribe sus carteles y las coloca en vitrinas. Al terminar comprueba que puedan verse desde el pasillo.','¿De qué trata el texto?','Preparar una muestra de juguetes','una muestra de juguetes antiguos','Las tareas están orientadas a organizar esa muestra.','Construir un museo','Las ventanas del pasillo'),
('Los chicos reparan bicicletas en el taller del barrio. Revisan frenos y ruedas, cambian las piezas gastadas y prueban cada bicicleta antes de entregarla.','¿Cuál es el tema?','La reparación de bicicletas','Revisan frenos y ruedas','Revisar, cambiar piezas y probar son etapas de la reparación.','Una carrera de bicicletas','Todos los transportes del barrio')])
unit('leng_res_detalles','leng_res_tema','Separar lo esencial de un detalle','Para contar lo principal no hace falta repetir cada dato. Conservamos qué pasó, a quién y el resultado importante. Probamos quitar un detalle: si todavía se entiende el hecho central, puede quedar fuera del resumen. Un color o una hora pueden importar en otros textos; depende de lo que expliquen.','Probá quitar el dato y comprobá si se sigue entendiendo lo principal.',[
('La clase organizó una colecta para la biblioteca. Cada familia aportó libros y al final reunieron cien. La caja donde los guardaron tenía una cinta violeta.','¿Qué detalle puede omitirse al resumir la colecta?','La cinta violeta de la caja','reunieron cien','El aporte de las familias y el resultado explican la colecta. El color de la cinta no cambia ese hecho.','Que las familias aportaron libros','Que reunieron cien libros'),
('Una rama bloqueaba el sendero. Los vecinos la retiraron y el camino volvió a quedar libre. Uno de ellos llevaba una gorra verde.','¿Qué puede quedar fuera del resumen del problema y su solución?','El color de la gorra','el camino volvió a quedar libre','La rama y su retiro explican la solución; la gorra no interviene.','La rama que bloqueaba el sendero','Que retiraron la rama'),
('La escuela cambió una canilla que perdía agua. Después de la reparación dejó de gotear. La caja de herramientas era amarilla.','¿Qué detalle no hace falta para resumir la reparación?','El color de la caja','dejó de gotear','La pérdida y su solución son esenciales; el color de la caja no explica el arreglo.','La pérdida de agua','El resultado de la reparación'),
('El equipo de teatro olvidó la música grabada. Una compañera tocó la guitarra y pudieron hacer la función. La guitarra tenía una pegatina de una estrella.','¿Qué detalle se puede omitir sin perder la solución?','La pegatina de la guitarra','Una compañera tocó la guitarra','Tocar en vivo permitió hacer la función. La pegatina no explica cómo resolvieron el problema.','Que faltaba la música grabada','Que una compañera tocó en vivo'),
('La biblioteca amplió su horario para que pudieran ir quienes salen tarde de la escuela. Ahora abre también después de las seis. En la entrada colocaron una maceta cuadrada.','¿Qué dato puede quedar fuera de un resumen sobre el nuevo horario?','La forma de la maceta','amplió su horario','El cambio de horario y su finalidad son centrales; la forma de la maceta no los explica.','Que abre después de las seis','Para quién ampliaron el horario'),
('El grupo marcó las cajas con colores para no mezclar semillas. Guardó las de flores en la caja roja y las de verduras en la azul. Trabajó sobre una mesa redonda.','¿Qué detalle puede omitirse al resumir cómo evitaron la mezcla?','La forma de la mesa','marcó las cajas con colores','Aquí los colores sí ayudan a organizar las semillas. La forma de la mesa no cumple esa función.','Que usaron colores para distinguir cajas','Qué semillas guardaron en cada caja')])
unit('leng_res_titulo','leng_lect_3_idea_central','Elegir un título que abarque el texto','Un título breve puede anticipar el tema o la idea principal. Comparamos cada título con todo el texto: debe abarcar lo importante, sin centrarse solo en un detalle ni prometer algo que no se cuenta.','Elegí un título que sirva para el texto entero.',[
('Los vecinos reservaron una esquina de la plaza para intercambiar plantas. Cada persona lleva una y elige otra. Junto a las macetas dejan consejos para cuidarlas.','¿Qué título abarca mejor el texto?','Un intercambio de plantas en la plaza','intercambiar plantas','El título reúne la actividad y su lugar; los consejos forman parte del intercambio.','Consejos junto a una maceta','Una competencia de jardinería'),
('En la escuela, cada curso eligió cuentos para leer a los más pequeños. Practicaron en voz alta y prepararon encuentros semanales. Al final de cada lectura conversan sobre la historia.','¿Qué título elegirías?','Cuentos compartidos entre cursos','leer a los más pequeños','El texto trata de organizar y compartir lecturas, no solo de practicar la voz.','Cómo ganar un concurso de cuentos','Una práctica de voz'),
('El club arregló una sala vacía para que los vecinos pudieran reunirse. Pintó las paredes, agregó mesas y puso un calendario para reservar turnos. Desde entonces varios grupos la usan.','¿Qué título resume el asunto principal?','Una sala para reunirse en el club','para que los vecinos pudieran reunirse','Los arreglos y los turnos hacen posible ese uso compartido.','El calendario de una pared','La construcción de un estadio'),
('Durante una semana, la clase anotó cuánto papel desechaba. Después decidió usar ambas caras de las hojas y reunir los recortes. Al mes siguiente llenó menos bolsas de papel usado.','¿Qué título representa todo el texto?','Menos papel desperdiciado en la clase','llenó menos bolsas de papel usado','El texto une la observación, las decisiones y la reducción del desperdicio.','Las bolsas del mes siguiente','Una clase que dejó de escribir'),
('Para conocer la historia del barrio, los alumnos entrevistaron a vecinos mayores. Reunieron fotos y escribieron sus relatos. Luego armaron una muestra abierta a las familias.','¿Qué título abarca la lectura?','La historia del barrio contada por sus vecinos','Para conocer la historia del barrio','Las entrevistas, las fotos y la muestra sirven a ese propósito común.','Una foto antigua','Un viaje a otra ciudad'),
('La biblioteca armó mochilas con libros para quienes viven lejos. Cada semana una voluntaria las lleva a distintos hogares y recoge las de la semana anterior. Así más familias pueden leer.','¿Cuál es el título más adecuado?','Libros que llegan a los hogares','Así más familias pueden leer','La entrega y la devolución acercan la lectura a familias alejadas.','La compra de mochilas nuevas','El cierre de una biblioteca')])
unit('leng_res_reformular','leng_res_titulo','Decir una idea con otras palabras','Reformular es expresar la misma idea de otra manera. Podemos cambiar palabras y ordenar la frase, pero conservamos quién actúa, qué hace y las relaciones importantes. No cambiamos un intento por un logro ni algunas personas por todas.','Compará quién, qué pasó y si se conserva el mismo alcance.',[
('Los vecinos reunieron dinero para reparar el techo del salón. Todavía no empezaron la obra: primero deben conseguir los materiales.','¿Qué frase dice lo mismo que la primera oración?','Juntaron dinero para arreglar el techo','reunieron dinero para reparar el techo','Juntar y reunir expresan aquí lo mismo; la frase no afirma que la obra esté terminada.','Terminaron de arreglar el techo','Repararon todos los edificios'),
('Algunos alumnos prefieren leer en el patio durante el recreo. Otros eligen jugar o conversar.','¿Qué reformulación conserva el sentido de la primera frase?','Una parte de los alumnos elige leer en el patio','Algunos alumnos prefieren leer','Algunos indica una parte, no todos ni ninguno.','Todos los alumnos leen en el patio','Ningún alumno quiere jugar'),
('El club suspendió el paseo porque el puente estaba cerrado. Avisó a las familias antes de la salida.','¿Qué frase expresa la misma causa?','El cierre del puente impidió realizar el paseo','porque el puente estaba cerrado','Se conserva la relación entre el puente cerrado y la suspensión.','El paseo provocó el cierre del puente','Las familias cerraron el puente'),
('La biblioteca presta libros por una semana. Quien necesita más tiempo puede pedir una renovación.','¿Qué frase conserva lo dicho en la primera oración?','Los libros se pueden llevar prestados durante siete días','presta libros por una semana','Siete días equivale a una semana; sigue siendo un préstamo.','La biblioteca regala libros cada semana','Todos deben terminar un libro en un día'),
('El equipo intentó alcanzar la cima, pero regresó al refugio antes de llegar porque comenzó una tormenta.','¿Qué frase conserva el resultado?','Quisieron llegar a la cima, pero volvieron antes','regresó al refugio antes de llegar','El intento no se convirtió en llegada. El resumen debe conservar que regresaron.','Llegaron a la cima durante la tormenta','No salieron del refugio'),
('La nueva rampa permite entrar al salón sin subir escalones. La puerta sigue en el mismo lugar.','¿Cuál expresa lo mismo que la primera frase?','Con la rampa se puede ingresar sin usar escalones','sin subir escalones','Ingresar y entrar tienen aquí el mismo sentido. No se cambió la puerta.','Movieron la puerta a otro lugar','La rampa obliga a subir escalones')])
unit('leng_res_unir','leng_res_reformular','Unir las ideas de dos párrafos','Leemos un párrafo por vez y decimos qué aporta cada uno. Después unimos sus ideas principales. Si uno presenta un problema y el otro una solución, el resumen necesita ambos. Podemos usar por eso o después solo cuando esa relación aparece en el texto.','Buscá qué aporta cada párrafo y conservá ambas ideas.',[
('En la biblioteca había libros que nadie encontraba. Estaban mezclados en cajas y los carteles se habían perdido.\n\nEl grupo los ordenó por temas y escribió nuevas etiquetas. Desde entonces los lectores pueden ubicarlos sin abrir todas las cajas.','¿Qué resumen reúne los dos párrafos?','Los libros eran difíciles de encontrar; los ordenaron y etiquetaron para ubicarlos','los ordenó por temas y escribió nuevas etiquetas','El resumen conserva el problema del primer párrafo y la solución del segundo.','Había cajas en la biblioteca','Compraron libros porque las cajas estaban vacías'),
('En el patio no había sombra cerca de los bancos. Los alumnos evitaban sentarse allí al mediodía.\n\nLa escuela colocó un toldo sobre ese sector. Ahora los bancos quedan a la sombra y vuelven a usarse durante el recreo.','¿Qué resumen incluye lo esencial de ambos párrafos?','Un toldo dio sombra a los bancos y permitió volver a usarlos','Ahora los bancos quedan a la sombra','Se conserva la falta de sombra y el cambio que resolvió esa dificultad.','Los alumnos se sientan en bancos','Quitaron los bancos para construir un patio'),
('El grupo recibía tantas hojas sueltas que perdía avisos de la escuela. Algunas notas quedaban dentro de libros y otras en mochilas.\n\nDecidió guardar todos los avisos en una carpeta común. Cada día alguien revisa si hay una nota nueva para compartirla.','¿Qué resumen une problema y organización?','Para no perder avisos, el grupo los guarda y revisa en una carpeta común','guardar todos los avisos en una carpeta común','La carpeta y la revisión responden a la pérdida de notas del primer párrafo.','Las mochilas tienen libros','La escuela dejó de mandar avisos'),
('Los carteles del sendero se habían borrado. Quienes visitaban el parque no sabían qué camino llevaba al lago.\n\nLos guardaparques repintaron las flechas y agregaron un mapa en la entrada. Así los visitantes pueden elegir el recorrido.','¿Qué resumen conserva lo principal?','Renovaron las señales del sendero para orientar a los visitantes','repintaron las flechas y agregaron un mapa','Las señales nuevas solucionan la falta de orientación.','En el parque hay un lago','Cerraron el parque porque nadie quería visitarlo'),
('El club quería ofrecer juegos de mesa, pero tenía pocos. Invitó a las familias a donar los que ya no usaban.\n\nLlegaron juegos de distintas edades. Un equipo revisó sus piezas y organizó tardes para compartirlos.','¿Qué resumen reúne ambas partes?','El club reunió juegos donados y organizó encuentros para usarlos','organizó tardes para compartirlos','La colecta y los encuentros forman las dos etapas centrales.','Algunos juegos tienen muchas piezas','El club compró todos los juegos nuevos'),
('La clase escribió cuentos para una muestra. Al leerlos en voz alta, descubrió que algunas partes no se entendían.\n\nLos autores agregaron información y cambiaron frases confusas. Después compartieron las versiones revisadas con las familias.','¿Qué resumen incluye el proceso completo?','La clase revisó sus cuentos para que se entendieran antes de compartirlos','cambiaron frases confusas','Se conserva la dificultad encontrada y la revisión previa a la muestra.','Las familias escucharon cuentos','Los autores borraron todos los cuentos y no hicieron la muestra')])
unit('leng_res_revisar','leng_res_unir','Revisar que el resumen sea fiel','Volvemos del resumen al texto y comprobamos cada afirmación. Revisamos si cambió quién hizo algo, si se invirtió una causa, si se agregó un dato o si falta el resultado principal. Un resumen puede ser breve y aun así estar equivocado.','Compará la afirmación del resumen con lo que realmente dice el texto.',[
('El grupo quería plantar diez árboles, pero consiguió seis. Plantó esos seis y decidió buscar más para el mes siguiente.','Un resumen dice: «El grupo plantó diez árboles». ¿Qué hay que corregir?','Plantó seis; diez era la cantidad que quería','consiguió seis. Plantó esos seis','El resumen confundió el propósito con lo realizado.','No hay que corregir nada','Plantó dieciséis árboles'),
('La función empezó tarde porque falló una luz del escenario. Cuando la repararon, los actores pudieron comenzar.','Un resumen dice: «La función empezó tarde porque los actores no llegaron». ¿Qué hay que corregir?','La causa fue la falla de una luz','porque falló una luz del escenario','El resumen agregó una causa que el texto no dice.','Los actores llegaron al día siguiente','No hay que corregir nada'),
('Las familias donaron telas al taller. Los alumnos las usaron para fabricar bolsas reutilizables.','Un resumen dice: «Los alumnos donaron telas a las familias». ¿Qué cambió?','Se intercambiaron quienes donaron y quienes recibieron','Las familias donaron telas al taller','El resumen invierte los participantes y omite el uso de las telas.','Cambió el día de la donación','No cambió nada importante'),
('El club reunió juguetes para compartir. Separó los que estaban rotos, reparó varios y organizó una tarde de juegos con los que podían usarse.','Un resumen dice: «El club reunió juguetes». ¿Qué conviene agregar para contar el resultado?','Que preparó los juguetes y organizó una tarde de juegos','organizó una tarde de juegos','La frase inicial es verdadera, pero omite lo que hicieron con la colecta.','El precio de cada juguete','El color de todas las cajas'),
('La biblioteca ensayó un horario nuevo durante dos semanas. Después consultará a los lectores para decidir si lo mantiene.','Un resumen dice: «La biblioteca decidió mantener para siempre el nuevo horario». ¿Qué debe cambiar?','Todavía falta consultar y decidir si lo mantienen','para decidir si lo mantiene','El texto describe una prueba, no una decisión definitiva.','La biblioteca cerró para siempre','No debe cambiar nada'),
('La clase encontró errores en un mapa del barrio. Los corrigió y entregó una copia nueva al centro vecinal.','Un resumen dice: «La clase corrigió un mapa y compartió la versión nueva». ¿Es fiel al texto?','Sí, conserva las acciones principales','Los corrigió y entregó una copia nueva','La frase reformula sin inventar hechos ni cambiar el resultado.','No, debería decir que tiraron el mapa','No, debería decir que construyeron otro barrio')])
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8');start='// R17: idea principal y resumen.';end='// FIN R17'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst RESUMEN_R17 = '+json.dumps(U,ensure_ascii=False,indent=2)+""";
for (const unidad of RESUMEN_R17) {
 const indice=UNIDADES_BASES.findIndex(u=>u.id===unidad.despues_de);
 if(indice<0)throw new Error('Falta el paso anterior de '+unidad.id);
 UNIDADES_BASES.splice(indice+1,0,unidad);
}
"""+end+'\n\n';i=min(s.index(marker) for marker in ['// R18: escritura guiada.','export const TEMAS_BASES'] if marker in s);p.write_text(s[:i]+code+s[i:],encoding='utf-8');print(len(U),'unidades;',len(U)*6,'actividades')
